<section id="bucketsView" class="view-panel">
    <div class="files-page-heading"><div><p class="eyebrow">STORAGE WORKSPACE</p><h1>Your storage</h1><p>A place for your files. A little more room to stay organized.</p></div><button id="newBucketTopButton" class="button" type="button"><span aria-hidden="true">＋</span> New bucket</button></div>
    <div class="files-layout">
        <aside class="buckets-sidebar">
            <div class="buckets-sidebar-heading"><div><h2>Your buckets</h2><p>A home for every project</p></div><span id="bucketCount">0</span></div>
            <div id="bucketList" class="thin-scrollbar" aria-label="Storage buckets"></div>
            <form id="bucketForm"><label for="bucketName">NEW BUCKET</label><input id="bucketName" placeholder="e.g. product-images" pattern="[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]" required aria-describedby="bucketNameHelp"><p id="bucketNameHelp">Lowercase letters, numbers, dots or hyphens.</p><button type="submit">＋ Create bucket</button></form>
            <div class="sidebar-note"><svg aria-hidden="true"><use href="#icon-lock"/></svg><p>Your buckets are only visible to your account.</p></div>
        </aside>
        <section class="file-workspace" aria-labelledby="bucketTitle">
            <header class="file-workspace-heading"><div class="bucket-breadcrumb"><svg aria-hidden="true"><use href="#icon-box"/></svg><span>Buckets</span><span aria-hidden="true">/</span><strong id="bucketTitle">Select a bucket</strong></div><button id="refreshObjects" class="file-icon-button" aria-label="Refresh files" title="Refresh files" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/></svg></button></header>
            <div id="bucketIntegration" class="bucket-integration" hidden>
                <div><span class="bucket-detail-label">Bucket ID</span><code id="selectedBucketId"></code><button id="copyBucketId" class="file-icon-button" type="button" aria-label="Copy bucket ID" title="Copy bucket ID"><svg aria-hidden="true"><use href="#icon-copy"/></svg></button></div>
                <div><span class="bucket-detail-label">Upload API</span><span class="bucket-http-method">POST</span><code id="bucketUploadEndpoint"></code><button id="copyBucketUploadUrl" class="file-icon-button" type="button" aria-label="Copy upload API URL" title="Copy upload API URL"><svg aria-hidden="true"><use href="#icon-copy"/></svg></button></div>
            </div>
            <div class="bucket-overview"><div><span id="statFiles">—</span><p>Files in this bucket</p></div><div><span id="statStorage">—</span><p>Total file size</p></div><div><span id="statPrivate">—</span><p>Private files</p></div></div>
            <form id="uploadForm" class="file-upload hidden"><div class="upload-caption"><span class="upload-emblem"><svg aria-hidden="true"><use href="#icon-upload"/></svg></span><div><strong>Bring a file in</strong><span>Choose a file, set its access, and upload.</span></div></div><div class="upload-controls"><input id="uploadFile" type="file" required aria-label="Choose a file to upload"><select id="uploadVisibility" aria-label="Upload access"><option value="private">Private</option><option value="public">Public</option></select><button id="uploadSubmit" class="button" type="submit"><svg aria-hidden="true"><use href="#icon-upload"/></svg><span>Upload</span></button></div></form>
            <div class="file-list-heading"><div><h2>Files</h2><p id="bucketHint" aria-live="polite">Choose a bucket to view its files.</p></div><span class="file-private-note"><svg aria-hidden="true"><use href="#icon-lock"/></svg> Private links expire automatically</span></div>
            <div class="file-toolbar"><label class="file-search" for="objectSearch"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="objectSearch" type="search" placeholder="Search files in this bucket…" autocomplete="off"></label><div class="file-filters"><select id="objectVisibility" aria-label="Filter files by access"><option value="all">All access</option><option value="private">Private only</option><option value="public">Public only</option></select><select id="objectSort" aria-label="Sort files"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="name">Name A–Z</option><option value="largest">Largest first</option></select></div></div>
            <div id="fileLoading" class="file-loading" hidden role="status">Loading your files…</div>
            <div id="fileListError" class="file-list-error" hidden role="alert"></div>
            <table id="objectTable" class="object-table"><colgroup><col class="name-column"><col class="access-column"><col class="size-column"><col class="date-column"><col class="actions-column"></colgroup><thead><tr><th>File name</th><th>Access</th><th class="file-size-cell">Size</th><th class="file-date-cell">Added</th><th class="file-actions-cell" aria-label="File actions"></th></tr></thead><tbody id="objectTableBody"></tbody></table>
            <div id="objectEmpty" class="file-empty hidden"><span><svg aria-hidden="true"><use href="#icon-file"/></svg></span><h3 id="objectEmptyTitle">A little room for your next file.</h3><p id="objectEmptyHint">Choose a file above to get this bucket started.</p><button id="clearFileFilters" class="backup-secondary" type="button" hidden>Clear filters</button></div>
            <footer class="file-list-footer"><span id="filePageSummary">No bucket selected</span><div><button id="previousObjectPage" type="button" aria-label="Previous page" disabled>← Previous</button><span id="objectPageNumber">Page 1</span><button id="nextObjectPage" type="button" aria-label="Next page" disabled>Next →</button></div></footer>
        </section>
    </div>
</section>
